import json,csv,collections,pathlib,re
P=pathlib.Path('D1/c1');D=json.load(open(P/'part-alma.1.details.json'));C=json.load(open(P/'part-alma.1.checks.json'));T={r['id']:r for r in csv.DictReader(open(P/'part-alma.1.tsv'),delimiter='\t')}
sentences={}
for l in open('SENTENCES.md'):
 m=re.match(r'- \*\*(S[\d.-]+)\*\* (.*)',l)
 if m:sentences[m[1]]=m[2]
used=set(s for r in T.values() for s in r['sentences'].split(','))
with open(P/'part-alma.1.notes.md','w') as f:
 f.write('# Stored-member classification notes\n\nScope: 1,647 input groups, 7,286 complete immediate member records. Only the assigned input, retained raw inventory, fixed text, and public program documentation were consulted. No other classification was consulted.\n\n')
 f.write('## Interpretation and evidence\n\nThe input groups represent their listed immediate children. A listed child directory is evaluated as that directory, not recursively substituted by descendants. The filesystem traversal explicitly records persistence per member; persistent temporary directories were not called runtime merely because their names contain `tmp`. The runtime exception precedes the four object questions. All other members follow the questions in order. `executable=true` on a directory means search permission and does not establish code.\n\n')
 f.write('Raw sources: `D1/in/raw/alma/raw/0004-filesystem.out`, `D1/in/raw/alma/package-files.tsv`, `D1/in/raw/alma/raw/0019-package-files-rpm.out`, `D1/in/raw/alma/metadata.json`, the input rows, and every member file identified below. The raw filesystem symlink targets establish `/lib`, `/lib64`, `/bin`, `/sbin` as aliases of their corresponding `/usr` directories. Package matching normalizes only these observed aliases. No full-content equality is inferred from prefix hashes.\n\n')
 f.write('Package directories appear in the raw RPM manifest but were omitted from the integrity table. A manifest location alone does not establish that a directory remains as received. Unresolved directories therefore remain UNKNOWN unless their documented generated-cache function establishes a program record. Package reasons do not alter coverage of an unchanged member by its package line. Missing lock records and per-file provenance explicitly remain unresolved for npm installation contents.\n\n')
 f.write('`UNKNOWN` in a mixed member list means that member cannot be assigned a determinate class from retained facts. It is not a hypothetical text gap. Public documentation supplies program function and format, not unobserved installation history. Where a runtime creator has UNKNOWN integrity/provenance, the member is still RUNTIME because its own volatility is established independently. The parent runtime filesystem setting is UNKNOWN as to own/default line where no more specific creating program is established.\n\n')
 f.write('## Exact deciding sentences\n\n')
 for s in sorted(used):f.write(f'- **{s}** {sentences[s]}\n')
 f.write('\n## Public documentation\n\n')
 refs=[('pip','https://pip.pypa.io/en/stable/topics/caching/','A new cache format is now used, stored in a directory called `http-v2`'),('npm','https://docs.npmjs.com/cli/v8/commands/npm-cache/','npm stores cache data in an opaque directory within the configured `cache`, named `_cacache`.'),('DNF','https://dnf.readthedocs.io/en/latest/conf_ref.html','Path to a directory used by various DNF subsystems for storing cache data.'),('fontconfig','https://xorg.freedesktop.org/archive/X11R7.0/doc/html/fc-cache.1.html','These files are generated by fc-cache and contain maps from file names to font properties.'),('man-db','https://manpages.debian.org/bookworm/man-db/mandb.8.en.html','mandb is used to initialise or manually update index database caches.'),('Python','https://docs.python.org/3/faq/programming.html','to create a `__pycache__` subdirectory and write the compiled module to that subdirectory.'),('Firefox telemetry','https://firefox-source-docs.mozilla.org/toolkit/components/telemetry/concepts/archiving.html','pings submitted to `TelemetryController` are also stored locally in the user profile directory'),('systemd hierarchy','https://www.freedesktop.org/software/systemd/man/253/file-hierarchy.html','A "`tmpfs`" file system for system packages to place runtime data, socket files, and similar.')]
 for label,url,q in refs:f.write(f'- [{label}]({url}): “{q}”\n')
 f.write('\nThe hierarchy documentation also identifies `/var/log` as persistent system logs. Cache and log rules concern their stored data representations and directory structures. They do not treat executable bytecode as ordinary records. Python rules apply only to the directory named `__pycache__`, never to its compiled files. Unknown browser startup-code caches were not subsumed under the data-cache rule.\n\n')
 f.write('## Rules and manual checks\n\n')
 rules={'package':'Every immediate member is persistent and joins an unchanged installed-package record, after observed alias resolution. S8.2-7 and S8.2-8 answer question 1 affirmatively; S8.2-16 gives INSTALLED-PACKAGE.', 'runtime':'Every immediate member has runtime backing. S8.2-5 gives RUNTIME independently of its name or code capability. The output names the known creating program and its decision, or the runtime-filesystem setting with UNKNOWN provenance.', 'cache':'Every member is documented program-generated cache, log, archive data, or its generated directory structure; it is not installed payload, executable code, or a selected setting. S8.2-15 gives RECORD. Documentation identifies pip HTTP data, npm cache data, DNF metadata, font information maps, manual-page indexes, telemetry archives, logs, and Python cache directories.', 'unknown':'Retained facts do not establish the first applicable question or its required recording line. Missing package integrity, installation defaults, source provenance, or executable content can change the answer. S8.2-6 requires preserving question order; no later guessed class overrides the missing fact.', 'mixed':'Evaluate each complete immediate member separately. Emit MIXED when member decisions differ; the exact member partition is recorded below. This is row-by-row composition of the preceding rules, not a classification from the directory name.'}
 byid={d['id']:d for d in D}
 for rule,txt in rules.items():
  f.write(f'### {rule}\n\n{txt}\n\nManual checks (10 rows):\n\n')
  for id in C[rule]:
   d=byid[id];counts=collections.Counter(m['decision'] for m in d['members']);f.write(f'- `{id}`: {len(d["members"])} members; '+', '.join(f'{k}={v}' for k,v in sorted(counts.items()))+'. Confirmed member types, persistence, and the applicable provenance/format condition against the raw list.\n')
 f.write('\nThe single sudo rule was evaluated individually: `alma-9b55d85b3e8beb263c1f1957`. The retained content in `raw/0226-metadata-read-0.out` grants passwordless administrative access in a local sudoers fragment, producing SETTING-OWN under S8.2-11–13 and S8.2-17.\n\n')
 f.write('## Evidence corrections during this attempt\n\nInitial exact-path joins were replaced by verified filesystem-alias joins before the first output rows. A later documentation pass resolved manual indexes, telemetry archives, logs, and generated Python cache directories previously marked UNKNOWN. Their enclosing mixed groups were recalculated. These are evidence corrections within this attempt, not changes to the definition. Final counts and validation refer to the corrected output.\n\n')
 f.write('## Complete member decisions\n\nMember names below are relative to each named group. `$USER_HOME` and `$ROOT_HOME` replace private home-directory prefixes. Each source is the unmodified complete member TSV; no inferred members are added.\n\n')
 for d in D:
  id=d['id'];r=T[id];f.write(f'### {id}\n\nGroup: `{d["directory"]}`. Source: `D1/in/raw/alma/members/{id[5:]}.tsv`. Decision: **{r["decision"]}**.\n\n')
  f.write(r['reason']+'\n\n')
  groups=collections.defaultdict(list)
  for m in d['members']:groups[(m['decision'],m['reason'])].append(m['member'].rsplit('/',1)[-1])
  for (decision,reason),names in groups.items():f.write('- **'+decision+'**: '+', '.join('`'+n+'`' for n in names)+'. '+reason+'\n')
 csv.field_size_limit(10000000)
 inp=[r['id'] for r in csv.DictReader(open('D1/in/part-alma.tsv'),delimiter='\t') if r['kind']=='L2:stored-ownership-unresolved']
 out=list(csv.DictReader(open(P/'part-alma.1.tsv'),delimiter='\t'))
 allowed=set('INSTALLED-OWN INSTALLED-PACKAGE INSTALLED-DERIVED PROGRAM-OWN PROGRAM-DERIVED SETTING-OWN SETTING-DEFAULT RECORD MATERIAL RUNTIME ACTION GAP-NONE GAP-TWO UNKNOWN MIXED'.split())
 assert len(inp)==len(out)==len({r['id'] for r in out})==1647
 assert set(inp)=={r['id'] for r in out}
 for r in out:
  assert r['decision'] in allowed
  assert len(r['what_it_does'].split())<=15,(r['id'],'what')
  assert len(r['reason'].split())<=30,(r['id'],'reason')
  assert all(s in sentences for s in r['sentences'].split(','))
 counts=collections.Counter(r['decision'] for r in out)
 f.write('\n## Final validation\n\nValidated exact assigned input/output ID set and count, uniqueness, all 15 permitted decision values, sentence IDs, field lengths, and complete member counts.\n\n')
 for k,v in sorted(counts.items()):f.write(f'- {k}: {v}\n')
print(dict(sorted(counts.items())))
